// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 a, uint256 b) public {
        uint256 maxSafe = type(uint256).max / 4;
        if (a > maxSafe || b > maxSafe) return;

        address caller = address(0xABCD);
        vm.prank(caller);
        bool ok1;
        try c.SetMinSum(a) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        vm.prank(caller);
        bool ok2;
        try c.SetMinSum(b) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        if (!ok1 || !ok2) return;

        assertTrue(c.MinSum() == b);
    }
}
